=== OwnerAddress ===
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.Map;

/**
 * Single source of truth for the owner address normalisation rule used across the
 * {@code POST /owners} pipeline: an address is canonicalised by trimming, collapsing internal
 * whitespace to single spaces, upper-casing, and expanding common abbreviations as whole words
 * ({@code ST}→{@code STREET}, {@code RD}→{@code ROAD}, {@code AVE}→{@code AVENUE}). So
 * {@code "  12  main  st "} canonicalises to {@code "12 MAIN STREET"} and {@code "7 elm ave"} to
 * {@code "7 ELM AVENUE"}.
 *
 * <p>Centralised here (rather than inlined) so every site agrees on one definition:
 * {@link ValidateOwnerFields} stores the canonical value and rejects a value that is blank once
 * normalised, while {@link OwnerHousehold} compares the canonical value for duplicate detection
 * and the shared household id.
 */
final class OwnerAddress {

    /** Whole-word abbreviations expanded during normalisation. */
    private static final Map<String, String> ABBREVIATIONS = Map.of(
            "ST", "STREET",
            "RD", "ROAD",
            "AVE", "AVENUE");

    private OwnerAddress() {
    }

    /**
     * The stored/returned/compared form: trimmed, internal whitespace collapsed to single
     * spaces, upper-cased, with common abbreviations expanded as whole words. Returns an empty
     * string for a null or whitespace-only input.
     */
    static String normalize(String address) {
        if (address == null) {
            return "";
        }
        String trimmed = address.trim();
        if (trimmed.isEmpty()) {
            return "";
        }
        String[] tokens = trimmed.toUpperCase(Locale.ROOT).split("\\s+");
        StringBuilder sb = new StringBuilder();
        for (String token : tokens) {
            if (sb.length() > 0) {
                sb.append(' ');
            }
            sb.append(ABBREVIATIONS.getOrDefault(token, token));
        }
        return sb.toString();
    }
}
=== CityAtCapacityException ===
package org.springframework.samples.petclinic.rest.function.owner;

/**
 * Thrown by {@link CheckOwnerCityCapacity} when an owner create request targets a city that
 * already contains 50 or more owners. Checked so it appears in the {@code throws} clause and is
 * routed to its escalation handler, which responds 409.
 */
public class CityAtCapacityException extends Exception {

    public CityAtCapacityException(String city) {
        super("The city is at capacity and cannot accept more owners: " + city);
    }
}
=== InvalidTelephoneException ===
package org.springframework.samples.petclinic.rest.function.owner;

/**
 * Thrown by {@link NormalizeOwnerTelephone} when an owner create request carries a telephone
 * that cannot be canonicalised to E.164 form (a {@code '+'} followed by 8 to 15 digits). Checked
 * so it appears in the {@code throws} clause and is routed to its escalation handler, which
 * responds 400.
 */
public class InvalidTelephoneException extends Exception {

    public InvalidTelephoneException(String telephone) {
        super("Telephone must be a valid E.164 number (8 to 15 digits): " + telephone);
    }
}
=== NormalizeOwnerTelephone ===
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Create-time normalisation for {@code POST /owners}: canonicalises the telephone to E.164 form
 * (see {@link OwnerTelephone#toE164(String)}). The canonical value is written back onto the body
 * in place (the {@code @Val} object is the same instance {@link BuildOwner} then maps), so it is
 * what gets stored and returned. A value that cannot form a valid E.164 number is rejected with
 * 400 via {@link InvalidTelephoneException}.
 *
 * <p>Runs after {@link ValidateOwnerFields} (which has already guaranteed telephone is present
 * and non-blank) and before {@link BuildOwner}.
 */
public class NormalizeOwnerTelephone {

    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
        String original = request.getTelephone();
        String e164 = OwnerTelephone.toE164(original);
        if (e164 == null) {
            throw new InvalidTelephoneException(original);
        }
        request.setTelephone(e164);
    }
}

